import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT,
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    pw = hashlib.sha256(b'admin123').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email, api_key) VALUES ('admin', ?, 'admin', 'admin@corp.local', 'sk-admin-9f8e7d6c')", (pw,))
    db.commit()
    db.close()

@app.route('/api/user/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    # Value uses string formatting for LIKE pattern support
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/user/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key"""
    api_key = request.headers.get('X-API-Key', '')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute("SELECT username, email, role FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Invalid API key'}), 403

@app.route('/api/admin/logs', methods=['GET'])
def get_logs():
    """Admin endpoint to view audit logs"""
    api_key = request.headers.get('X-API-Key', '')
    db = get_db()
    user = db.execute("SELECT role FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if not user or user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    limit = request.args.get('limit', '50')
    logs = db.execute(f"SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT {limit}").fetchall()
    return jsonify([dict(l) for l in logs])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
